        "InvalidParameterValue"
    );
    assert_eq!(h.err(set("nope", json!({}))), "QueueDoesNotExist");
    assert_eq!(
        h.err(set("q", json!({"Fifo": false}))),
        "UnsupportedOperation"
    );
    assert_eq!(
        h.err(set("q", json!({"ContentBasedDeduplication": true}))),
        "InvalidParameterValue"
