    tag(&mut h, numbered(0..50));
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": numbered(49..51)}));
    assert_eq!(code, "LimitExceeded");
    assert_eq!(list(&mut h).as_object().unwrap().len(), 50);
    assert_eq!(list(&mut h)["k49"], "v");
