    let code = h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": numbered(0..51)}));
    assert_eq!(code, "LimitExceeded");
    assert_eq!(list(&mut h), json!({}));
}

#[test]
fn tags_are_not_attributes_and_survive_purge_and_idempotent_create() {
